    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient, address recipient2) public {
        bool revertedFirst;
        bool revertedSecond;
        uint balBefore = recipient.balance;

        try c.getFirstWithdrawalBonus(recipient) {
            revertedFirst = false;
        } catch {
            revertedFirst = true;
        }

        uint balAfterFirst = recipient.balance;

        uint amountToWithdraw = c.rewardsForA(recipient);
        c.withdrawReward(recipient);

        uint balAfterSecondWithdraw = recipient.balance;

        try c.getFirstWithdrawalBonus(recipient) {
            revertedSecond = false;
        } catch {
            revertedSecond = true;
        }

        assert(
            revertedFirst ||
